  INSERT INTO crm_courses(id,revision,value) VALUES
    ('4b7a59a2-cea5-4bf3-b8e4-102dd9bc4803', 1, REPLACE('{"name":"HSK 1 · New Concept Chinese · 23 × 45 min","sessions":23,"price":1150000,"active":true,"maxDiscountBps":0,"maxDiscountAmount":null,"teaching":{"level":"HSK 1","material":"New Concept Chinese","minutes":45,"knowledge":"","learningOutcomes":"","resources":"","introduction":{"en":{"audience":"For complete beginners. Start speaking Chinese from the first class and build confidence in everyday conversations step by step.","outcomes":"Introduce yourself in Chinese.\nUse basic expressions in everyday conversations.\nAsk and answer simple questions.\nUnderstand and use common Chinese words.\nRecognize and write basic Chinese characters.\nBuild simple Chinese sentences.\nBegin listening, speaking, reading and writing in Chinese.\nBuild a solid foundation in Chinese.\nDevelop confidence in everyday communication.\nPrepare for higher HSK levels.","topics":"This course uses New Concept Chinese, Book 1.\nThe full textbook covers 400+ common words, 300+ Chinese characters and 40+ grammar points across 20 units. Each unit has one main lesson, one review lesson and a communication activity.\nShort dialogues cover names and nationalities, introductions, apologies, hobbies, ordering food, shopping and asking for directions.\nCore language includes personal pronouns, 这 and 那 (this and that), yes/no questions with 吗 and negatives with 不.","practice":"In class: listen and answer using textbook prompts, then practise short exchanges aloud.\nNew Concept Chinese online exercises: review vocabulary and sentence patterns.\nHSK mock questions: practise listening and reading in a test format.\nClass recordings: revisit explanations and examples from the lesson."},"id":{"audience":"Untuk pemula tanpa pengalaman belajar bahasa Mandarin. Mulai berbicara sejak kelas pertama dan bangun rasa percaya diri untuk percakapan sehari-hari secara bertahap.","outcomes":"Memperkenalkan diri dalam bahasa Mandarin.\nMenggunakan ungkapan dasar dalam percakapan sehari-hari.\nMengajukan dan menjawab pertanyaan sederhana.\nMemahami dan menggunakan kata-kata umum dalam bahasa Mandarin.\nMengenali dan menulis aksara Han dasar.\nMenyusun kalimat sederhana dalam bahasa Mandarin.\nMulai berlatih menyimak, berbicara, membaca, dan menulis dalam bahasa Mandarin.\nMembangun dasar bahasa Mandarin yang kuat.\nMembangun rasa percaya diri untuk berkomunikasi sehari-hari.\nMempersiapkan diri untuk jenjang HSK yang lebih tinggi.","topics":"Kursus ini menggunakan New Concept Chinese, Buku 1.\nBuku ini terdiri dari 20 unit yang mencakup lebih dari 400 kata umum, lebih dari 300 aksara Han, dan lebih dari 40 pokok tata bahasa. Setiap unit berisi satu pelajaran utama, satu pelajaran pengulangan, dan satu kegiatan komunikasi.\nDialog singkatnya mencakup nama dan kewarganegaraan, perkenalan, permintaan maaf, hobi, cara memesan makanan, berbelanja, dan bertanya arah.\nDasar bahasa mencakup kata ganti orang, 这 dan 那 (ini dan itu), pertanyaan ya/tidak dengan 吗, serta bentuk negatif dengan 不.","practice":"Di kelas: simak rekaman, jawab dengan bantuan kata petunjuk, lalu berlatih percakapan singkat.\nLatihan daring New Concept Chinese: ulangi kosakata dan pola kalimat.\nSoal simulasi HSK: latih kemampuan menyimak dan membaca dengan format ujian.\nRekaman kelas: tinjau kembali penjelasan dan contoh dari sesi belajar."},"zh":{"audience":"适合零基础学员。从第一堂课开始开口说中文，逐步建立日常交流的信心。","outcomes":"用中文介绍自己。\n使用基本的日常表达。\n提出并回答简单问题。\n理解和使用常用中文词汇。\n辨认和书写基础汉字。\n用中文造简单的句子。\n开始练习中文听、说、读、写。\n打好中文基础。\n建立日常交流的信心。\n为学习更高等级的 HSK 做准备。","topics":"本课程使用《New Concept Chinese》第 1 册。\n教材全册有 20 个单元，涵盖 400 多个常用词、300 多个汉字和 40 多个语法项目。每个单元安排一课新内容、一课复习和一项交际活动。\n教材通过简短对话练习询问姓名和国籍、自我介绍、致歉、谈爱好、点餐、购物和问路。\n基础语言包括人称代词、指示词「这／那」、用「吗」提问和用「不」否定。","practice":"课堂听说：按教材提示听录音、回答问题，再练习简短对话。\n《New Concept Chinese》线上练习：复习词汇和句型。\nHSK 模拟试题：练习考试形式的听力与阅读。\n课堂录像：回看课堂讲解和例句。"}}},"presetKey":"hsk_standard_v1","updatedAt":"UPER_BOOTSTRAP_AT","history":[{"id":"system-initialize-4b7a59a2-cea5-4bf3-b8e4-102dd9bc4803","actor":"system","at":"UPER_BOOTSTRAP_AT","before":null,"after":{"name":"HSK 1 · New Concept Chinese · 23 × 45 min","sessions":23,"price":1150000,"active":true,"maxDiscountBps":0,"maxDiscountAmount":null,"teaching":{"level":"HSK 1","material":"New Concept Chinese","minutes":45,"knowledge":"","learningOutcomes":"","resources":"","introduction":{"en":{"audience":"For complete beginners. Start speaking Chinese from the first class and build confidence in everyday conversations step by step.","outcomes":"Introduce yourself in Chinese.\nUse basic expressions in everyday conversations.\nAsk and answer simple questions.\nUnderstand and use common Chinese words.\nRecognize and write basic Chinese characters.\nBuild simple Chinese sentences.\nBegin listening, speaking, reading and writing in Chinese.\nBuild a solid foundation in Chinese.\nDevelop confidence in everyday communication.\nPrepare for higher HSK levels.","topics":"This course uses New Concept Chinese, Book 1.\nThe full textbook covers 400+ common words, 300+ Chinese characters and 40+ grammar points across 20 units. Each unit has one main lesson, one review lesson and a communication activity.\nShort dialogues cover names and nationalities, introductions, apologies, hobbies, ordering food, shopping and asking for directions.\nCore language includes personal pronouns, 这 and 那 (this and that), yes/no questions with 吗 and negatives with 不.","practice":"In class: listen and answer using textbook prompts, then practise short exchanges aloud.\nNew Concept Chinese online exercises: review vocabulary and sentence patterns.\nHSK mock questions: practise listening and reading in a test format.\nClass recordings: revisit explanations and examples from the lesson."},"id":{"audience":"Untuk pemula tanpa pengalaman belajar bahasa Mandarin. Mulai berbicara sejak kelas pertama dan bangun rasa percaya diri untuk percakapan sehari-hari secara bertahap.","outcomes":"Memperkenalkan diri dalam bahasa Mandarin.\nMenggunakan ungkapan dasar dalam percakapan sehari-hari.\nMengajukan dan menjawab pertanyaan sederhana.\nMemahami dan menggunakan kata-kata umum dalam bahasa Mandarin.\nMengenali dan menulis aksara Han dasar.\nMenyusun kalimat sederhana dalam bahasa Mandarin.\nMulai berlatih menyimak, berbicara, membaca, dan menulis dalam bahasa Mandarin.\nMembangun dasar bahasa Mandarin yang kuat.\nMembangun rasa percaya diri untuk berkomunikasi sehari-hari.\nMempersiapkan diri untuk jenjang HSK yang lebih tinggi.","topics":"Kursus ini menggunakan New Concept Chinese, Buku 1.\nBuku ini terdiri dari 20 unit yang mencakup lebih dari 400 kata umum, lebih dari 300 aksara Han, dan lebih dari 40 pokok tata bahasa. Setiap unit berisi satu pelajaran utama, satu pelajaran pengulangan, dan satu kegiatan komunikasi.\nDialog singkatnya mencakup nama dan kewarganegaraan, perkenalan, permintaan maaf, hobi, cara memesan makanan, berbelanja, dan bertanya arah.\nDasar bahasa mencakup kata ganti orang, 这 dan 那 (ini dan itu), pertanyaan ya/tidak dengan 吗, serta bentuk negatif dengan 不.","practice":"Di kelas: simak rekaman, jawab dengan bantuan kata petunjuk, lalu berlatih percakapan singkat.\nLatihan daring New Concept Chinese: ulangi kosakata dan pola kalimat.\nSoal simulasi HSK: latih kemampuan menyimak dan membaca dengan format ujian.\nRekaman kelas: tinjau kembali penjelasan dan contoh dari sesi belajar."},"zh":{"audience":"适合零基础学员。从第一堂课开始开口说中文，逐步建立日常交流的信心。","outcomes":"用中文介绍自己。\n使用基本的日常表达。\n提出并回答简单问题。\n理解和使用常用中文词汇。\n辨认和书写基础汉字。\n用中文造简单的句子。\n开始练习中文听、说、读、写。\n打好中文基础。\n建立日常交流的信心。\n为学习更高等级的 HSK 做准备。","topics":"本课程使用《New Concept Chinese》第 1 册。\n教材全册有 20 个单元，涵盖 400 多个常用词、300 多个汉字和 40 多个语法项目。每个单元安排一课新内容、一课复习和一项交际活动。\n教材通过简短对话练习询问姓名和国籍、自我介绍、致歉、谈爱好、点餐、购物和问路。\n基础语言包括人称代词、指示词「这／那」、用「吗」提问和用「不」否定。","practice":"课堂听说：按教材提示听录音、回答问题，再练习简短对话。\n《New Concept Chinese》线上练习：复习词汇和句型。\nHSK 模拟试题：练习考试形式的听力与阅读。\n课堂录像：回看课堂讲解和例句。"}}}}}]}', 'UPER_BOOTSTRAP_AT', v_at)),
    ('5cd7f25c-c2ed-4e67-b797-940c3fbb784a', 1, REPLACE('{"name":"HSK 2 · New Concept Chinese · 24 × 45 min","sessions":24,"price":2880000,"active":true,"maxDiscountBps":0,"maxDiscountAmount":null,"teaching":{"level":"HSK 2","material":"New Concept Chinese","minutes":45,"knowledge":"","learningOutcomes":"","resources":"","introduction":{"en":{"audience":"For learners with a basic Chinese foundation who want to speak more naturally, expand their vocabulary, and handle daily situations with greater confidence.","outcomes":"Carry on simple everyday conversations.\nTalk about work, study, and personal life.\nWork toward understanding and using 300+ common words.\nRecognize and write more Chinese characters.\nUse essential grammar patterns in conversation.\nUnderstand short passages and dialogues.\nImprove listening, speaking, reading, and writing.\nStrengthen your communication skills.\nUse a wider range of practical vocabulary.\nPrepare for HSK 3 and academic Chinese.","topics":"New Concept Chinese, Book 2, contains 20 units with two lessons each.\nThe full book covers 400+ common words, 300+ characters, and about 40 grammar points.\nTextbook topics include travel, etiquette, job hunting, renting a home, and making plans.","practice":"Listen to and read short dialogues, then practise using the expressions in conversation.\nUse the Book 2 companion workbook to review vocabulary, sentence patterns, and characters.\nNew Concept Chinese online exercises: review vocabulary and sentence patterns.\nHSK mock questions: practise listening and reading in a test format.\nClass recordings: revisit explanations and examples from the lesson."},"id":{"audience":"Untuk pelajar yang sudah memiliki dasar bahasa Mandarin dan ingin berbicara lebih alami, memperluas kosakata, serta lebih percaya diri dalam situasi sehari-hari.","outcomes":"Melakukan percakapan sederhana sehari-hari.\nMembicarakan pekerjaan, studi, dan kehidupan pribadi.\nBerlatih memahami dan menggunakan lebih dari 300 kata umum.\nMengenali dan menulis lebih banyak aksara Han.\nMenggunakan pola tata bahasa dasar dalam percakapan.\nMemahami bacaan pendek dan dialog.\nMeningkatkan kemampuan menyimak, berbicara, membaca, dan menulis.\nMemperkuat kemampuan berkomunikasi.\nMemperluas kosakata yang digunakan dalam situasi praktis.\nMempersiapkan diri untuk HSK 3 dan bahasa Mandarin akademis.","topics":"New Concept Chinese Buku 2 terdiri dari 20 unit, masing-masing dengan dua pelajaran.\nBuku ini secara keseluruhan mencakup lebih dari 400 kata umum, lebih dari 300 aksara Han, dan sekitar 40 pokok tata bahasa.\nTopik buku mencakup perjalanan, tata krama, mencari pekerjaan, menyewa tempat tinggal, dan membuat rencana.","practice":"Simak dan baca dialog singkat, lalu gunakan ungkapannya dalam percakapan.\nGunakan buku latihan pendamping Buku 2 untuk mengulang kosakata, pola kalimat, dan aksara Han.\nLatihan daring New Concept Chinese: ulangi kosakata dan pola kalimat.\nSoal simulasi HSK: latih kemampuan menyimak dan membaca dengan format ujian.\nRekaman kelas: tinjau kembali penjelasan dan contoh dari sesi belajar."},"zh":{"audience":"适合已有中文基础、希望说得更自然的学员。扩充词汇，逐步更有信心地应对日常情境。","outcomes":"进行简单的日常对话。\n谈论工作、学习和个人生活。\n以理解和使用 300 多个常用词为学习目标。\n辨认和书写更多汉字。\n在对话中使用基本语法和句型。\n理解短文和对话。\n提升听、说、读、写能力。\n加强沟通能力。\n扩大实际交流中使用的词汇范围。\n为 HSK 3 和学术中文学习做准备。","topics":"《New Concept Chinese》第 2 册共 20 个单元，每个单元 2 课。\n教材全册涵盖 400 多个常用词、300 多个汉字和约 40 个语法项目。\n教材话题包括旅行、礼仪、求职、租房和制订计划。","practice":"听读简短对话，再把里面的表达用于交流。\n用第 2 册配套练习册复习词汇、句型和汉字。\n《New Concept Chinese》线上练习：复习词汇和句型。\nHSK 模拟试题：练习考试形式的听力与阅读。\n课堂录像：回看课堂讲解和例句。"}}},"presetKey":"hsk_standard_v1","updatedAt":"UPER_BOOTSTRAP_AT","history":[{"id":"system-initialize-5cd7f25c-c2ed-4e67-b797-940c3fbb784a","actor":"system","at":"UPER_BOOTSTRAP_AT","before":null,"after":{"name":"HSK 2 · New Concept Chinese · 24 × 45 min","sessions":24,"price":2880000,"active":true,"maxDiscountBps":0,"maxDiscountAmount":null,"teaching":{"level":"HSK 2","material":"New Concept Chinese","minutes":45,"knowledge":"","learningOutcomes":"","resources":"","introduction":{"en":{"audience":"For learners with a basic Chinese foundation who want to speak more naturally, expand their vocabulary, and handle daily situations with greater confidence.","outcomes":"Carry on simple everyday conversations.\nTalk about work, study, and personal life.\nWork toward understanding and using 300+ common words.\nRecognize and write more Chinese characters.\nUse essential grammar patterns in conversation.\nUnderstand short passages and dialogues.\nImprove listening, speaking, reading, and writing.\nStrengthen your communication skills.\nUse a wider range of practical vocabulary.\nPrepare for HSK 3 and academic Chinese.","topics":"New Concept Chinese, Book 2, contains 20 units with two lessons each.\nThe full book covers 400+ common words, 300+ characters, and about 40 grammar points.\nTextbook topics include travel, etiquette, job hunting, renting a home, and making plans.","practice":"Listen to and read short dialogues, then practise using the expressions in conversation.\nUse the Book 2 companion workbook to review vocabulary, sentence patterns, and characters.\nNew Concept Chinese online exercises: review vocabulary and sentence patterns.\nHSK mock questions: practise listening and reading in a test format.\nClass recordings: revisit explanations and examples from the lesson."},"id":{"audience":"Untuk pelajar yang sudah memiliki dasar bahasa Mandarin dan ingin berbicara lebih alami, memperluas kosakata, serta lebih percaya diri dalam situasi sehari-hari.","outcomes":"Melakukan percakapan sederhana sehari-hari.\nMembicarakan pekerjaan, studi, dan kehidupan pribadi.\nBerlatih memahami dan menggunakan lebih dari 300 kata umum.\nMengenali dan menulis lebih banyak aksara Han.\nMenggunakan pola tata bahasa dasar dalam percakapan.\nMemahami bacaan pendek dan dialog.\nMeningkatkan kemampuan menyimak, berbicara, membaca, dan menulis.\nMemperkuat kemampuan berkomunikasi.\nMemperluas kosakata yang digunakan dalam situasi praktis.\nMempersiapkan diri untuk HSK 3 dan bahasa Mandarin akademis.","topics":"New Concept Chinese Buku 2 terdiri dari 20 unit, masing-masing dengan dua pelajaran.\nBuku ini secara keseluruhan mencakup lebih dari 400 kata umum, lebih dari 300 aksara Han, dan sekitar 40 pokok tata bahasa.\nTopik buku mencakup perjalanan, tata krama, mencari pekerjaan, menyewa tempat tinggal, dan membuat rencana.","practice":"Simak dan baca dialog singkat, lalu gunakan ungkapannya dalam percakapan.\nGunakan buku latihan pendamping Buku 2 untuk mengulang kosakata, pola kalimat, dan aksara Han.\nLatihan daring New Concept Chinese: ulangi kosakata dan pola kalimat.\nSoal simulasi HSK: latih kemampuan menyimak dan membaca dengan format ujian.\nRekaman kelas: tinjau kembali penjelasan dan contoh dari sesi belajar."},"zh":{"audience":"适合已有中文基础、希望说得更自然的学员。扩充词汇，逐步更有信心地应对日常情境。","outcomes":"进行简单的日常对话。\n谈论工作、学习和个人生活。\n以理解和使用 300 多个常用词为学习目标。\n辨认和书写更多汉字。\n在对话中使用基本语法和句型。\n理解短文和对话。\n提升听、说、读、写能力。\n加强沟通能力。\n扩大实际交流中使用的词汇范围。\n为 HSK 3 和学术中文学习做准备。","topics":"《New Concept Chinese》第 2 册共 20 个单元，每个单元 2 课。\n教材全册涵盖 400 多个常用词、300 多个汉字和约 40 个语法项目。\n教材话题包括旅行、礼仪、求职、租房和制订计划。","practice":"听读简短对话，再把里面的表达用于交流。\n用第 2 册配套练习册复习词汇、句型和汉字。\n《New Concept Chinese》线上练习：复习词汇和句型。\nHSK 模拟试题：练习考试形式的听力与阅读。\n课堂录像：回看课堂讲解和例句。"}}}}}]}', 'UPER_BOOTSTRAP_AT', v_at)),
    ('74516bc0-f265-4225-8698-7133a95059e6', 1, REPLACE('{"name":"HSK 3 · New Concept Chinese · 42 × 45 min","sessions":42,"price":5040000,"active":true,"maxDiscountBps":0,"maxDiscountAmount":null,"teaching":{"level":"HSK 3","material":"New Concept Chinese","minutes":45,"knowledge":"","learningOutcomes":"","resources":"","introduction":{"en":{"audience":"For learners with basic conversational Chinese who want to use it in real situations, from daily life and work to travelling or studying in China.","outcomes":"Handle everyday conversations in Chinese.\nCommunicate in study settings and basic workplace situations.\nTravel in China with greater confidence.\nWork toward understanding and using 400+ common words.\nWork toward recognizing and writing 300+ Chinese characters.\nPractise applying around 40 key grammar patterns.\nUse listening, speaking, reading, and writing together in Chinese.\nMake progress toward the language requirements of Chinese universities.\nBuild a stronger foundation in academic Chinese.\nBe better prepared to study in China.","topics":"New Concept Chinese connects vocabulary, characters, and sentence patterns with situations in daily life, study, and work.\nThe numbers above are course learning targets. The textbook series covers practical topics such as travelling, finding a job, and making plans.","practice":"Practise conversations for travel, study, and the workplace.\nUse short texts for listening, reading, and retelling, then write a response using the same expressions.\nNew Concept Chinese online exercises: review vocabulary and sentence patterns.\nHSK mock questions: practise listening and reading in a test format.\nClass recordings: revisit explanations and examples from the lesson."},"id":{"audience":"Untuk pelajar yang sudah bisa bercakap sederhana dan ingin memakai bahasa Mandarin dalam situasi nyata, mulai dari kehidupan sehari-hari dan pekerjaan hingga bepergian atau studi di Tiongkok.","outcomes":"Melakukan percakapan sehari-hari dalam bahasa Mandarin.\nBerkomunikasi dalam situasi belajar dan situasi kerja dasar.\nLebih percaya diri saat bepergian di Tiongkok.\nBerlatih memahami dan menggunakan lebih dari 400 kata umum.\nBerlatih mengenali dan menulis lebih dari 300 aksara Han.\nBerlatih menerapkan sekitar 40 pola tata bahasa utama.\nMenggunakan kemampuan menyimak, berbicara, membaca, dan menulis dalam bahasa Mandarin.\nSemakin siap memenuhi persyaratan bahasa perguruan tinggi di Tiongkok.\nMembangun dasar bahasa Mandarin akademis yang lebih kuat.\nLebih siap untuk menempuh studi di Tiongkok.","topics":"New Concept Chinese mengaitkan kosakata, aksara, dan pola kalimat dengan kehidupan sehari-hari, studi, dan pekerjaan.\nAngka di atas adalah sasaran belajar kursus. Seri buku ini memuat topik praktis seperti perjalanan, mencari pekerjaan, dan membuat rencana.","practice":"Latih percakapan untuk perjalanan, studi, dan pekerjaan.\nSimak, baca, dan ceritakan kembali teks pendek, lalu tulis tanggapan dengan ungkapan yang sama.\nLatihan daring New Concept Chinese: ulangi kosakata dan pola kalimat.\nSoal simulasi HSK: latih kemampuan menyimak dan membaca dengan format ujian.\nRekaman kelas: tinjau kembali penjelasan dan contoh dari sesi belajar."},"zh":{"audience":"适合已能用中文做简单交流、想把中文用到真实情境中的学员。学习在日常、工作以及赴华旅行和学习中运用中文。","outcomes":"用中文应对日常交流。\n在学习和基础工作情境中沟通。\n更有信心地在中国旅行。\n以理解和使用 400 多个常用词为学习目标。\n以辨认和书写 300 多个汉字为学习目标。\n练习运用约 40 个核心语法结构。\n综合运用中文听、说、读、写能力。\n更接近中国高校的语言要求。\n打下更扎实的学术中文基础。\n为赴华学习做更充分的准备。","topics":"《New Concept Chinese》用日常生活、学习和工作的情境串联词汇、汉字和句型。\n以上数字是课程学习目标。该系列教材包含旅行、求职和制订计划等实用话题。","practice":"练习旅行、学习和工作中的实际对话。\n听读并复述短文，再用相同的表达写一段回应。\n《New Concept Chinese》线上练习：复习词汇和句型。\nHSK 模拟试题：练习考试形式的听力与阅读。\n课堂录像：回看课堂讲解和例句。"}}},"presetKey":"hsk_standard_v1","updatedAt":"UPER_BOOTSTRAP_AT","history":[{"id":"system-initialize-74516bc0-f265-4225-8698-7133a95059e6","actor":"system","at":"UPER_BOOTSTRAP_AT","before":null,"after":{"name":"HSK 3 · New Concept Chinese · 42 × 45 min","sessions":42,"price":5040000,"a