    ('3abe725a-d334-4b3c-8c49-12b679fe09b6', 1, REPLACE('{"name":"HSK 4 · New Concept Chinese · 84 × 45 min","sessions":84,"price":10080000,"active":true,"maxDiscountBps":0,"maxDiscountAmount":null,"teaching":{"level":"HSK 4","material":"New Concept Chinese","minutes":45,"knowledge":"","learningOutcomes":"","resources":"","introduction":{"en":{"audience":"One online HSK 4 course with two stages. HSK 4A builds your intermediate foundation. HSK 4B completes the HSK 4 learning pathway and prepares you for using Chinese in China.","stages":{"4A":{"audience":"For learners ready to build an intermediate Chinese foundation after developing basic communication skills.","outcomes":"Handle conversations in daily life, study, and basic workplace situations.\nDescribe experiences and situations more clearly.\nUnderstand longer sentences and common real-life topics.\nWork toward using 500+ new words in communication.\nBuild a strong foundation for the full HSK 4 level.\nBegin to understand classroom Chinese and practical Chinese.\nMove beyond basic communication.\nPrepare to complete the HSK 4 learning pathway.","topics":"New Concept Chinese, Book 3, covers 579 common words across the full volume.\nThe full volume includes 303 Chinese characters.\nThe full volume includes 40 grammar points.\nThe book has 20 one-lesson units on study, daily life, and work.","practice":"Practise describing experiences with longer sentences and discussing familiar situations.\nUse the Book 3 companion workbook to reinforce vocabulary, characters, and grammar."},"4B":{"audience":"For learners ready to build on HSK 4A and work toward full HSK 4 proficiency for further study and practical communication.","outcomes":"Communicate confidently in study, work, and social situations.\nExpress opinions, give reasons, and explain ideas clearly.\nUnderstand structured conversations and longer material.\nWork toward using 600+ new words in real situations.\nWork toward full HSK 4 proficiency.\nPrepare to apply to university programs in China when you meet their language and other entry requirements.\nGet closer to the language requirements for Chinese Government Scholarship (CSC) applications.\nBuild skills that can make you more competitive for jobs requiring Mandarin.","topics":"New Concept Chinese, Book 4, covers about 600 common words across the full volume.\nThe full volume includes more than 200 Chinese characters.\nThe full volume includes 40 grammar points.\nThe book has 20 one-lesson units. University and scholarship requirements vary by program, including any official HSK score required.","practice":"Use longer texts and structured conversations to practise explaining opinions and reasons.\nThe Book 4 companion workbook has exercises in vocabulary, grammar, listening, characters, communication, and extended texts."}},"practice":"New Concept Chinese online exercises: review vocabulary and sentence patterns.\nHSK mock questions: practise listening and reading in a test format.\nClass recordings: revisit explanations and examples from the lesson."},"id":{"audience":"Satu kursus daring HSK 4 dengan dua tahap. HSK 4A membangun dasar tingkat menengah. HSK 4B melengkapi jalur belajar HSK 4 dan mempersiapkan penggunaan bahasa Mandarin di Tiongkok.","stages":{"4A":{"audience":"Untuk pelajar yang sudah bisa berkomunikasi secara dasar dan siap membangun kemampuan bahasa Mandarin tingkat menengah.","outcomes":"Melakukan percakapan dalam kegiatan sehari-hari, studi, dan situasi kerja dasar.\nMenggambarkan pengalaman dan situasi dengan lebih jelas.\nMemahami kalimat yang lebih panjang dan topik yang umum dijumpai.\nBerlatih menggunakan lebih dari 500 kata baru dalam komunikasi.\nMembangun dasar yang kuat untuk mencapai kemampuan HSK 4 secara penuh.\nMulai memahami bahasa Mandarin di kelas dan dalam situasi praktis.\nMelangkah melampaui komunikasi dasar.\nMempersiapkan diri untuk menuntaskan jalur belajar HSK 4.","topics":"New Concept Chinese Buku 3 secara keseluruhan mencakup 579 kata umum.\nBuku ini mencakup 303 aksara Han.\nBuku ini mencakup 40 pokok tata bahasa.\nBuku ini terdiri dari 20 unit, masing-masing satu pelajaran, tentang studi, kehidupan sehari-hari, dan pekerjaan.","practice":"Berlatih menceritakan pengalaman dengan kalimat lebih panjang dan mendiskusikan situasi yang sudah dikenal.\nGunakan buku latihan pendamping Buku 3 untuk memperkuat kosakata, aksara, dan tata bahasa."},"4B":{"audience":"Untuk pelajar yang siap melanjutkan dari HSK 4A menuju kemampuan HSK 4 secara penuh untuk studi dan komunikasi praktis.","outcomes":"Berkomunikasi dengan percaya diri dalam situasi studi, kerja, dan sosial.\nMenyampaikan pendapat, memberikan alasan, dan menjelaskan gagasan dengan jelas.\nMemahami percakapan terstruktur dan materi yang lebih panjang.\nBerlatih menggunakan lebih dari 600 kata baru dalam situasi nyata.\nMenuju kemampuan HSK 4 secara penuh.\nMempersiapkan pendaftaran ke perguruan tinggi di Tiongkok setelah memenuhi syarat bahasa dan syarat masuk lainnya.\nSemakin siap memenuhi persyaratan bahasa untuk mengajukan Beasiswa Pemerintah Tiongkok (CSC).\nMembangun kemampuan yang meningkatkan daya saing untuk pekerjaan yang membutuhkan bahasa Mandarin.","topics":"New Concept Chinese Buku 4 secara keseluruhan mencakup sekitar 600 kata umum.\nBuku ini mencakup lebih dari 200 aksara Han.\nBuku ini mencakup 40 pokok tata bahasa.\nBuku ini terdiri dari 20 unit, masing-masing satu pelajaran. Syarat perguruan tinggi dan beasiswa, termasuk skor HSK resmi, bergantung pada program tujuan.","practice":"Gunakan teks yang lebih panjang dan percakapan terstruktur untuk berlatih menyampaikan pendapat dan alasan.\nBuku latihan pendamping Buku 4 memuat latihan kosakata, tata bahasa, menyimak, aksara, komunikasi, dan wacana."}},"practice":"Latihan daring New Concept Chinese: ulangi kosakata dan pola kalimat.\nSoal simulasi HSK: latih kemampuan menyimak dan membaca dengan format ujian.\nRekaman kelas: tinjau kembali penjelasan dan contoh dari sesi belajar."},"zh":{"audience":"这是一门包含两个阶段的线上 HSK 4 课程。4A 建立中级基础，4B 衔接完整 HSK 4 学习目标，并为在中国使用中文做准备。","stages":{"4A":{"audience":"适合已有基础交流能力、准备打好中级中文基础的学员。","outcomes":"在日常生活、学习和基础工作场合进行交流。\n更清楚地描述经历和情境。\n理解较长的句子和常见的实际话题。\n以在交流中运用 500 多个新词为学习目标。\n为达到完整 HSK 4 水平打好基础。\n开始理解课堂中文和实际场景中的中文。\n从基础沟通迈向更丰富的表达。\n为完成 HSK 4 学习做准备。","topics":"《New Concept Chinese》第 3 册全册涵盖 579 个常用词。\n教材全册包含 303 个汉字。\n教材全册包含 40 个语法项目。\n全册 20 个单元，每单元 1 课，涵盖学习、生活和工作话题。","practice":"用较长的句子描述经历，讨论熟悉的情境。\n使用第 3 册配套练习册巩固词汇、汉字和语法。"},"4B":{"audience":"适合已完成 4A 或具有同等基础、希望继续提升中文能力以应对学习和实际交流的学员。","outcomes":"在学习、工作和社交场合自信交流。\n清楚地表达意见、给出理由并解释想法。\n理解有结构的对话和较长的内容。\n以在真实情境中运用 600 多个新词为学习目标。\n以达到完整 HSK 4 水平为目标。\n为申请中国高校项目做准备，申请须满足该项目的语言及其他入学条件。\n更接近中国政府奖学金（CSC）的语言申请要求。\n提升竞争需要中文能力的岗位所需的语言技能。","topics":"《New Concept Chinese》第 4 册全册涵盖约 600 个常用词。\n教材全册包含 200 多个汉字。\n教材全册包含 40 个语法项目。\n全册 20 个单元，每单元 1 课。高校与奖学金的申请条件及正式 HSK 成绩要求以目标项目为准。","practice":"用较长篇章和有结构的对话练习解释观点和理由。\n第 4 册配套练习册包含词汇、语法、听力、汉字、交际及语篇练习。"}},"practice":"《New Concept Chinese》线上练习：复习词汇和句型。\nHSK 模拟试题：练习考试形式的听力与阅读。\n课堂录像：回看课堂讲解和例句。"}}},"presetKey":"hsk_standard_v1","updatedAt":"UPER_BOOTSTRAP_AT","history":[{"id":"system-initialize-3abe725a-d334-4b3c-8c49-12b679fe09b6","actor":"system","at":"UPER_BOOTSTRAP_AT","before":null,"after":{"name":"HSK 4 · New Concept Chinese · 84 × 45 min","sessions":84,"price":10080000,"active":true,"maxDiscountBps":0,"maxDiscountAmount":null,"teaching":{"level":"HSK 4","material":"New Concept Chinese","minutes":45,"knowledge":"","learningOutcomes":"","resources":"","introduction":{"en":{"audience":"One online HSK 4 course with two stages. HSK 4A builds your intermediate foundation. HSK 4B completes the HSK 4 learning pathway and prepares you for using Chinese in China.","stages":{"4A":{"audience":"For learners ready to build an intermediate Chinese foundation after developing basic communication skills.","outcomes":"Handle conversations in daily life, study, and basic workplace situations.\nDescribe experiences and situations more clearly.\nUnderstand longer sentences and common real-life topics.\nWork toward using 500+ new words in communication.\nBuild a strong foundation for the full HSK 4 level.\nBegin to understand classroom Chinese and practical Chinese.\nMove beyond basic communication.\nPrepare to complete the HSK 4 learning pathway.","topics":"New Concept Chinese, Book 3, covers 579 common words across the full volume.\nThe full volume includes 303 Chinese characters.\nThe full volume includes 40 grammar points.\nThe book has 20 one-lesson units on study, daily life, and work.","practice":"Practise describing experiences with longer sentences and discussing familiar situations.\nUse the Book 3 companion workbook to reinforce vocabulary, characters, and grammar."},"4B":{"audience":"For learners ready to build on HSK 4A and work toward full HSK 4 proficiency for further study and practical communication.","outcomes":"Communicate confidently in study, work, and social situations.\nExpress opinions, give reasons, and explain ideas clearly.\nUnderstand structured conversations and longer material.\nWork toward using 600+ new words in real situations.\nWork toward full HSK 4 proficiency.\nPrepare to apply to university programs in China when you meet their language and other entry requirements.\nGet closer to the language requirements for Chinese Government Scholarship (CSC) applications.\nBuild skills that can make you more competitive for jobs requiring Mandarin.","topics":"New Concept Chinese, Book 4, covers about 600 common words across the full volume.\nThe full volume includes more than 200 Chinese characters.\nThe full volume includes 40 grammar points.\nThe book has 20 one-lesson units. University and scholarship requirements vary by program, including any official HSK score required.","practice":"Use longer texts and structured conversations to practise explaining opinions and reasons.\nThe Book 4 companion workbook has exercises in vocabulary, grammar, listening, characters, communication, and extended texts."}},"practice":"New Concept Chinese online exercises: review vocabulary and sentence patterns.\nHSK mock questions: practise listening and reading in a test format.\nClass recordings: revisit explanations and examples from the lesson."},"id":{"audience":"Satu kursus daring HSK 4 dengan dua tahap. HSK 4A membangun dasar tingkat menengah. HSK 4B melengkapi jalur belajar HSK 4 dan mempersiapkan penggunaan bahasa Mandarin di Tiongkok.","stages":{"4A":{"audience":"Untuk pelajar yang sudah bisa berkomunikasi secara dasar dan siap membangun kemampuan bahasa Mandarin tingkat menengah.","outcomes":"Melakukan percakapan dalam kegiatan sehari-hari, studi, dan situasi kerja dasar.\nMenggambarkan pengalaman dan situasi dengan lebih jelas.\nMemahami kalimat yang lebih panjang dan topik yang umum dijumpai.\nBerlatih menggunakan lebih dari 500 kata baru dalam komunikasi.\nMembangun dasar yang kuat untuk mencapai kemampuan HSK 4 secara penuh.\nMulai memahami bahasa Mandarin di kelas dan dalam situasi praktis.\nMelangkah melampaui komunikasi dasar.\nMempersiapkan diri untuk menuntaskan jalur belajar HSK 4.","topics":"New Concept Chinese Buku 3 secara keseluruhan mencakup 579 kata umum.\nBuku ini mencakup 303 aksara Han.\nBuku ini mencakup 40 pokok tata bahasa.\nBuku ini terdiri dari 20 unit, masing-masing satu pelajaran, tentang studi, kehidupan sehari-hari, dan pekerjaan.","practice":"Berlatih menceritakan pengalaman dengan kalimat lebih panjang dan mendiskusikan situasi yang sudah dikenal.\nGunakan buku latihan pendamping Buku 3 untuk memperkuat kosakata, aksara, dan tata bahasa."},"4B":{"audience":"Untuk pelajar yang siap melanjutkan dari HSK 4A menuju kemampuan HSK 4 secara penuh untuk studi dan komunikasi praktis.","outcomes":"Berkomunikasi dengan percaya diri dalam situasi studi, kerja, dan sosial.\nMenyampaikan pendapat, memberikan alasan, dan menjelaskan gagasan dengan jelas.\nMemahami percakapan terstruktur dan materi yang lebih panjang.\nBerlatih menggunakan lebih dari 600 kata baru dalam situasi nyata.\nMenuju kemampuan HSK 4 secara penuh.\nMempersiapkan pendaftaran ke perguruan tinggi di Tiongkok setelah memenuhi syarat bahasa dan syarat masuk lainnya.\nSemakin siap memenuhi persyaratan bahasa untuk mengajukan Beasiswa Pemerintah Tiongkok (CSC).\nMembangun kemampuan yang meningkatkan daya saing untuk pekerjaan yang membutuhkan bahasa Mandarin.","topics":"New Concept Chinese Buku 4 secara keseluruhan mencakup sekitar 600 kata umum.\nBuku ini mencakup lebih dari 200 aksara Han.\nBuku ini mencakup 40 pokok tata bahasa.\nBuku ini terdiri dari 20 unit, masing-masing satu pelajaran. Syarat perguruan tinggi dan beasiswa, termasuk skor HSK resmi, bergantung pada program tujuan.","practice":"Gunakan teks yang lebih panjang dan percakapan terstruktur untuk berlatih menyampaikan pendapat dan alasan.\nBuku latihan pendamping Buku 4 memuat latihan kosakata, tata bahasa, menyimak, aksara, komunikasi, dan wacana."}},"practice":"Latihan daring New Concept Chinese: ulangi kosakata dan pola kalimat.\nSoal simulasi HSK: latih kemampuan menyimak dan membaca dengan format ujian.\nRekaman kelas: tinjau kembali penjelasan dan contoh dari sesi belajar."},"zh":{"audience":"这是一门包含两个阶段的线上 HSK 4 课程。4A 建立中级基础，4B 衔接完整 HSK 4 学习目标，并为在中国使用中文做准备。","stages":{"4A":{"audience":"适合已有基础交流能力、准备打好中级中文基础的学员。","outcomes":"在日常生活、学习和基础工作场合进行交流。\n更清楚地描述经历和情境。\n理解较长的句子和常见的实际话题。\n以在交流中运用 500 多个新词为学习目标。\n为达到完整 HSK 4 水平打好基础。\n开始理解课堂中文和实际场景中的中文。\n从基础沟通迈向更丰富的表达。\n为完成 HSK 4 学习做准备。","topics":"《New Concept Chinese》第 3 册全册涵盖 579 个常用词。\n教材全册包含 303 个汉字。\n教材全册包含 40 个语法项目。\n全册 20 个单元，每单元 1 课，涵盖学习、生活和工作话题。","practice":"用较长的句子描述经历，讨论熟悉的情境。\n使用第 3 册配套练习册巩固词汇、汉字和语法。"},"4B":{"audience":"适合已完成 4A 或具有同等基础、希望继续提升中文能力以应对学习和实际交流的学员。","outcomes":"在学习、工作和社交场合自信交流。\n清楚地表达意见、给出理由并解释想法。\n理解有结构的对话和较长的内容。\n以在真实情境中运用 600 多个新词为学习目标。\n以达到完整 HSK 4 水平为目标。\n为申请中国高校项目做准备，申请须满足该项目的语言及其他入学条件。\n更接近中国政府奖学金（CSC）的语言申请要求。\n提升竞争需要中文能力的岗位所需的语言技能。","topics":"《New Concept Chinese》第 4 册全册涵盖约 600 个常用词。\n教材全册包含 200 多个汉字。\n教材全册包含 40 个语法项目。\n全册 20 个单元，每单元 1 课。高校与奖学金的申请条件及正式 HSK 成绩要求以目标项目为准。","practice":"用较长篇章和有结构的对话练习解释观点和理由。\n第 4 册配套练习册包含词汇、语法、听力、汉字、交际及语篇练习。"}},"practice":"《New Concept Chinese》线上练习：复习词汇和句型。\nHSK 模拟试题：练习考试形式的听力与阅读。\n课堂录像：回看课堂讲解和例句。"}}}}}]}', 'UPER_BOOTSTRAP_AT', v_at));
  IF @uper_business_digest IS NOT NULL THEN
    IF BINARY @uper_environment <> 'test' OR NOT REGEXP_LIKE(@uper_business_digest,'^[0-9a-f]{64}$','c') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Private business defaults are for the selected company-test database only';
    END IF;
    IF EXISTS(SELECT 1 FROM cms_collections c LEFT JOIN uper_seed_cms_collections s USING(name) WHERE s.name IS NULL)
       OR EXISTS(SELECT 1 FROM notification_rules r LEFT JOIN uper_seed_notification_rules s USING(id) WHERE s.id IS NULL)
       OR EXISTS(SELECT 1 FROM campaign_promotion_index p LEFT JOIN uper_seed_campaign_promotion_index s USING(p)
           WHERE s.p IS NULL OR s.campaign_id<>p.campaign_id)
       OR (SELECT COUNT(*) FROM uper_seed_trial_campaigns WHERE id IN ('organic','social-bio')
           AND code=id AND config->>'$.systemManaged'='true')<>2
       OR NOT EXISTS(SELECT 1 FROM uper_seed_notification_channels WHERE id='lark-group-default'
           AND COALESCE(config->>'$.deleted','false')<>'true')
       OR NOT EXISTS(SELECT 1 FROM uper_seed_enrollment_mail_configuration WHERE environment='test')
       OR (SELECT COUNT(*) FROM uper_seed_portal_settings WHERE id IN ('sla','lark_personal_channel'))<>2 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Private business defaults are missing required system starting values';
    END IF;

    DELETE FROM crm_courses;
    INSERT INTO crm_courses SELECT * FROM uper_seed_crm_courses;
    INSERT INTO enrollment_classes SELECT * FROM uper_seed_enrollment_classes;
    DELETE FROM portal_settings WHERE id IN ('sla','lark_personal_channel');
    INSERT INTO portal_settings SELECT * FROM uper_seed_portal_settings;
    DELETE FROM cms_collections;
    INSERT INTO cms_collections SELECT * FROM uper_seed_cms_collections;
    INSERT INTO cms_media SELECT * FROM uper_seed_cms_media;
    DELETE FROM campaign_promotion_index;
    DELETE FROM trial_campaigns;
    INSERT INTO trial_campaigns SELECT * FROM uper_seed_trial_campaigns;
    INSERT INTO campaign_promotion_index SELECT * FROM uper_seed_campaign_promotion_index;
    DELETE FROM rule_versions;
    DELETE FROM notification_rules;
    INSERT INTO notification_rules SELECT * FROM uper_seed_notification_rules;
    INSERT INTO rule_versions(id,version,config) SELECT id,version,config FROM notification_rules;
    DELETE FROM notification_channels;
    INSERT INTO notification_channels SELECT * FROM uper_seed_notification_channels;
    UPDATE enrollment_mail_configuration AS target
      JOIN uper_seed_enrollment_mail_configuration AS source USING(environment)
      SET target.revision=source.revision,
          target.config=JSON_SET(source.config,'$.delivery.generation',UUID())
      WHERE target.environment=@uper_environment;
  END IF;
  INSERT INTO portal_settings(id,value) VALUES
    ('empty_bootstrap_system_v20',JSON_MERGE_PATCH(
      JSON_OBJECT('batch','uper:empty-v20:20261126213651','environment',@uper_environment),
      JSON_OBJECT('businessDigest',@uper_business_digest)));
  COMMIT;
END//
DELIMITER ;
CALL uper_bootstrap_empty_system_v20();
DROP PROCEDURE uper_bootstrap_empty_system_v20;
DO RELEASE_LOCK(@uper_bootstrap_lock);
